      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"150\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"200\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"20\">DAY 3: EF 30%, acute on chronic HF</text><text x=\"550\" y=\"250\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">DAY 5: just \"heart failure\"</text><text x=\"550\" y=\"290\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Specificity dropped - what now?</text><rect x=\"150\" y=\"370\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.1)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"420\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">ANSWER: QUERY THE PHYSICIAN</text><text x=\"550\" y=\"465\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"17\">Ask if the specific diagnosis still applies</text><text x=\"550\" y=\"500\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"17\">and should be reflected at discharge</text><text x=\"550\" y=\"535\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\">Never assume or infer - always confirm</text></svg>",
